vec3 vec3_normalize(const vec3& v) {
    double length = std::sqrt(v.x * v.x + v.y * v.y + v.z * v.z);
    if (length > 0) {
        return vec3{v.x / length, v.y / length, v.z / length};
    }
    return v;
}

vec3 vec3_normalize(const vec3& v) {
    double length = std::sqrt(v.x * v.x + v.y * v.y + v.z * v.z);
    if (length > 0) {
        vec3 result;
        result.x = v.x / length;
        result.y = v.y / length;
        result.z = v.z / length;
        return result;
    }
    return v;
}

